        return .{
            .allocator = allocator,
            .contexts = ArrayList([]f64).init(allocator),
            .interference = 0.0,
        };
    }

    pub fn deinit(self: *QSM) void {
        for (self.contexts.items) |ctx| {
            self.allocator.free(ctx);
        }
        self.contexts.deinit();
    }

    pub fn multiplex(self: *QSM, synapse: f64, contexts: []const []const f64) !void {
        self.interference = 0.0;
        for (contexts) |ctx| {
            var phase: f64 = 0.0;
            var amp: f64 = 0.0;
            for (ctx) |c| {
                phase += math.pi * c;
                amp += c / 10.0;
            }
            self.interference += math.sin(phase + 0.1) * amp;
        }
        self.interference *= synapse;
    }

    pub fn getInterference(self: *const QSM) f64 {
        return self.interference;
    }
};

pub const MES = struct {
    allocator: Allocator,
    codec: *const fn (allocator: Allocator, str: []const u8) ![]u8,
    condition: bool,

    pub fn init(allocator: Allocator) MES {
        return .{
            .allocator = allocator,
            .codec = &defaultCodec,
            .condition = false,
        };
    }

    pub fn deinit(self: *MES) void {
        _ = self;
    }

    pub fn selfOverwrite(self: *MES, cond: bool) void {
        self.condition = cond;
    }

    pub fn process(self: *MES, input: []const u8) ![]u8 {
        if (self.condition) {
            return reverseString(self.allocator, input);
        } else {
            return self.codec.?(self.allocator, input);
        }
    }

    fn defaultCodec(allocator: Allocator, input: []const u8) ![]u8 {
        const result = try allocator.alloc(u8, input.len);
        @memcpy(result, input);
        return result;
    }

    fn reverseString(allocator: Allocator, s: []const u8) ![]u8 {
        const len = s.len;
        const result = try allocator.alloc(u8, len);
        for (0..len) |i| {
            result[i] = s[len - 1 - i];
        }
