    tokenizer: tokenizer.Tokenizer,
    optimizer: optimizer.ZOOptimizer,
    runtime: runtime.Runtime,

    pub const DType = enum { f64, f32, i64, i32 };

    pub fn init(allocator: Allocator, shape: []const usize, dtype: DType) !TensorCore {
        const total_size = blk: {
            var size: usize = 1;
            for (shape) |dim| {
                size *= dim;
            }
            break :blk size;
        };
        const data = try allocator.alloc(f64, total_size);
        @memset(data, 0.0);
        var qsm = QSM.init(allocator);
        var mes = MES.init(allocator);
        var ehm = EHM.init(allocator);
        var mxsi = MXSI.init();
        var cps = CPS.init(allocator);
