        var opt = optimizer.ZOOptimizer.init(allocator);
        var rt = runtime.Runtime.init(allocator);
        var tensor = TensorCore{
            .allocator = allocator,
            .shape = try allocator.dupe(usize, shape),
            .data = data,
            .dtype = dtype,
            .qsm = qsm,
            .mes = mes,
            .ehm = ehm,
            .mxsi = mxsi,
            .cps = cps,
            .tokenizer = tok,
            .optimizer = opt,
            .runtime = rt,
        };
        return tensor;
    }

    pub fn deinit(self: *TensorCore) void {
        self.qsm.deinit();
        self.mes.deinit();
        self.ehm.deinit();
        self.cps.deinit();
        self.tokenizer.deinit();
        self.optimizer.deinit();
        self.runtime.deinit();
        self.allocator.free(self.shape);
        self.allocator.free(self.data);
    }

    pub fn reshape(self: *TensorCore, new_shape: []const usize) !void {
        const old_total = blk: {
            var size: usize = 1;
            for (self.shape) |dim| {
                size *= dim;
            }
            break :blk size;
        };
        const new_total = blk: {
            var size: usize = 1;
            for (new_shape) |dim| {
                size *= dim;
            }
            break :blk size;
        };
        if (old_total != new_total) {
            return error.InvalidShape;
        }
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
    }

    pub fn add(self: *TensorCore, other: *const TensorCore) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, other.data) |*val, o| {
            val.* += o;
        }
    }

    pub fn mul(self: *TensorCore, other: *const TensorCore) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, other.data) |*val, o| {
            val.* *= o;
        }
    }

    pub fn matmul(self: *const TensorCore, other: *const TensorCore, allocator: Allocator) !TensorCore {
        if (self.shape.len != 2 or other.shape.len != 2) return error.NotMatrix;
        if (self.shape[1] != other.shape[0]) return error.InvalidDimensions;
        const rows = self.shape[0];
        const cols = other.shape[1];
        const inner = self.shape[1];
        var result = try TensorCore.init(allocator, &[_]usize{ rows, cols }, .f64);
        for (0..rows) |i| {
            for (0..cols) |j| {
                var sum: f64 = 0.0;
                for (0..inner) |k| {
                    sum += self.data[i * inner + k] * other.data[k * cols + j];
                }
                result.data[i * cols + j] = sum;
            }
        }
        return result;
    }

    pub fn softmax(self: *TensorCore, axis: usize) !void {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        if (axis == 0) {
            for (0..cols) |j| {
                var max_val: f64 = -math.inf(f64);
                var exp_sum: f64 = 0.0;
                for (0..rows) |i| {
                    max_val = math.max(max_val, self.data[i * cols + j]);
                }
                for (0..rows) |i| {
                    const shifted = self.data[i * cols + j] - max_val;
                    const exp_val = math.exp(shifted);
                    self.data[i * cols + j] = exp_val;
                    exp_sum += exp_val;
                }
                const inv_sum = 1.0 / exp_sum;
                for (0..rows) |i| {
                    self.data[i * cols + j] *= inv_sum;
                }
            }
        } else {
            for (0..rows) |i| {
                var max_val: f64 = -math.inf(f64);
                var exp_sum: f64 = 0.0;
                for (0..cols) |j| {
                    max_val = math.max(max_val, self.data[i * cols + j]);
                }
                for (0..cols) |j| {
                    const shifted = self.data[i * cols + j] - max_val;
                    const exp_val = math.exp(shifted);
                    self.data[i * cols + j] = exp_val;
                    exp_sum += exp_val;
                }
                const inv_sum = 1.0 / exp_sum;
                for (0..cols) |j| {
                    self.data[i * cols + j] *= inv_sum;
                }
            }
        }
    }

    pub fn argmax(self: *const TensorCore, allocator: Allocator, axis: usize) !TensorCore {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        var result_shape: [1]usize = if (axis == 0) .{cols} else .{rows};
        var result = try TensorCore.init(allocator, &result_shape, .i64);
        const data_len = result.data.len;
        for (0..data_len) |idx| {
            result.data[idx] = @as(f64, @floatFromInt(idx));
        }
        const data_i64 = @as([*]i64, @ptrCast(@alignCast(mem.sliceAsBytes(result.data).ptr)))[0..data_len];
        if (axis == 0) {
            for (0..cols) |j| {
                var max_idx: i64 = 0;
                var max_val = self.data[0 * cols + j];
                for (1..rows) |i| {
                    if (self.data[@as(usize, @intCast(i)) * cols + j] > max_val) {
                        max_val = self.data[@as(usize, @intCast(i)) * cols + j];
                        max_idx = @as(i64, @intCast(i));
                    }
                }
                data_i64[j] = max_idx;
            }
        } else {
            for (0..rows) |i| {
                var max_idx: i64 = 0;
                var max_val = self.data[i * cols + 0];
                for (1..cols) |j| {
                    if (self.data[i * cols + j] > max_val) {
                        max_val = self.data[i * cols + j];
                        max_idx = @as(i64, @intCast(j));
                    }
                }
                data_i64[i] = max_idx;
            }
        }
        for (0..data_len) |idx| {
            result.data[idx] = @as(f64, data_i64[idx]);
        }
        return result;
    }

    pub fn integrateQSM(self: *TensorCore, synapse: f64, contexts: [][]const f64) !void {
        try self.qsm.multiplex(synapse, contexts);
        const interf = self.qsm.getInterference();
        for (self.data) |*val| {
            val.* += interf;
        }
    }

    pub fn applyMES(self: *TensorCore, cond: bool, input_str: []const u8) !void {
        self.mes.selfOverwrite(cond);
        const processed = try self.mes.process(input_str);
        defer self.allocator.free(processed);
        for (self.data) |*val| {
            val.* += @as(f64, @floatFromInt(processed.len)) * 0.01;
        }
    }

    pub fn reflectEHM(self: *TensorCore, refl: []const u8) !void {
        try self.ehm.update(refl);
        const state = self.ehm.getState();
        for (self.data) |*val| {
            val.* *= state;
        }
    }

    pub fn adjustMXSI(self: *TensorCore, v: f64, t: f64) void {
        self.mxsi.compute(v, t);
        const cond = self.mxsi.getConductance();
        for (self.data) |*val| {
            val.* *= cond;
        }
    }

    pub fn phaseCPS(self: *TensorCore, thoughts: [][]const u8) !void {
        self.cps.thoughts.clearAndFree();
        for (thoughts) |th| {
            try self.cps.addThought(th);
        }
        try self.cps.computeTopology();
        const topology = self.cps.getTopology();
        for (topology, 0..) |top, i| {
            if (i < self.data.len) {
                self.data[i] += top.phase;
            }
        }
    }

    pub fn tokenize(self: *TensorCore, text: []const u8) ![]usize {
        return try self.tokenizer.tokenize(text);
    }

    pub fn optimize(self: *TensorCore, params: []f64) !void {
        try self.optimizer.optimize(params);
    }

    pub fn run(self: *TensorCore, input: []f64) ![]f64 {
        return try self.runtime.run(input);
    }

    pub fn hardwareAccel(self: *TensorCore, data: []f64) ![]f64 {
        return try hardware.accelerate(data);
    }

    fn shapeMatches(self: *const TensorCore, other: *const TensorCore) bool {
        if (self.shape.len != other.shape.len) return false;
        for (self.shape, other.shape) |s, o| {
            if (s != o) return false;
        }
        return true;
    }
};

