const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;

pub const Tokenizer = struct {
    allocator: Allocator,
    vocab: ArrayList([]u8),
    vocab_size: usize,

    pub fn init(allocator: Allocator) !Tokenizer {
        return Tokenizer{
            .allocator = allocator,
            .vocab = ArrayList([]u8).init(allocator),
            .vocab_size = 0,
        };
    }

    pub fn deinit(self: *Tokenizer) void {
        for (self.vocab.items) |word| {
            self.allocator.free(word);
        }
        self.vocab.deinit();
    }

    pub fn tokenize(self: *Tokenizer, text: []const u8) ![]usize {
        var tokens = ArrayList(usize).init(self.allocator);
        var i: usize = 0;
        while (i < text.len) {
            const token_id = self.findOrAddToken(text[i .. i + 1]) catch continue;
            try tokens.append(token_id);
            i += 1;
        }
        return tokens.toOwnedSlice();
    }

    fn findOrAddToken(self: *Tokenizer, token: []const u8) !usize {
        for (self.vocab.items, 0..) |word, idx| {
            if (mem.eql(u8, word, token)) {
                return idx;
            }
        }
        const new_token = try self.allocator.dupe(u8, token);
        try self.vocab.append(new_token);
        self.vocab_size += 1;
        return self.vocab_size - 1;
    }

    pub fn detokenize(self: *Tokenizer, tokens: []const usize) ![]u8 {
        var result = ArrayList(u8).init(self.allocator);
        for (tokens) |token_id| {
            if (token_id < self.vocab.items.len) {
                try result.appendSlice(self.vocab.items[token_id]);
            }
        }
        return result.toOwnedSlice();
    }
};
