const ArrayList = std.ArrayList;

pub const ZOOptimizer = struct {
    allocator: Allocator,
    learning_rate: f64,
    momentum: f64,
    velocity: []f64,

    pub fn init(allocator: Allocator) ZOOptimizer {
        return ZOOptimizer{
            .allocator = allocator,
            .learning_rate = 0.001,
            .momentum = 0.9,
            .velocity = &.{},
        };
    }

    pub fn deinit(self: *ZOOptimizer) void {
        self.allocator.free(self.velocity);
    }

    pub fn optimize(self: *ZOOptimizer, params: []f64) !void {
        if (self.velocity.len != params.len) {
            self.allocator.free(self.velocity);
            self.velocity = try self.allocator.alloc(f64, params.len);
            @memset(self.velocity, 0.0);
        }
        for (params, self.velocity) |*p, *v| {
            const grad = self.computeGradient(p.*);
            v.* = self.momentum * v.* + self.learning_rate * grad;
            p.* -= v.*;
        }
    }

    fn computeGradient(self: *ZOOptimizer, param: f64) f64 {
        _ = self;
        return param * 0.01;
    }

    pub fn setLearningRate(self: *ZOOptimizer, lr: f64) void {
        self.learning_rate = lr;
    }

    pub fn setMomentum(self: *ZOOptimizer, mom: f64) void {
        self.momentum = mom;
    }
