const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;

pub const Runtime = struct {
    allocator: Allocator,
    state: []f64,
    cache: ArrayList([]f64),

    pub fn init(allocator: Allocator) Runtime {
        return Runtime{
            .allocator = allocator,
            .state = &.{},
            .cache = ArrayList([]f64).init(allocator),
        };
    }

    pub fn deinit(self: *Runtime) void {
        self.allocator.free(self.state);
        for (self.cache.items) |item| {
            self.allocator.free(item);
        }
        self.cache.deinit();
    }

    pub fn run(self: *Runtime, input: []f64) ![]f64 {
        if (self.state.len != input.len) {
            self.allocator.free(self.state);
            self.state = try self.allocator.alloc(f64, input.len);
        }
        for (input, self.state) |in_val, *st_val| {
            st_val.* = in_val * 1.1;
        }
        const output = try self.allocator.dupe(f64, self.state);
        try self.cache.append(output);
        return output;
    }

    pub fn clearCache(self: *Runtime) void {
        for (self.cache.items) |item| {
            self.allocator.free(item);
        }
        self.cache.clearAndFree();
    }

    pub fn getState(self: *const Runtime) []const f64 {
        return self.state;
    }
};
