const std = @import("std");
const math = std.math;
const mem = std.mem;

pub fn accelerate(data: []f64) ![]f64 {
    const allocator = std.heap.page_allocator;
    const result = try allocator.alloc(f64, data.len);
    for (data, result) |d, *r| {
        r.* = d * 2.0;
    }
    return result;
}

pub fn optimizeMemory(data: []f64) void {
    for (data) |*d| {
        d.* = math.clamp(d.*, -1000.0, 1000.0);
    }
}

pub fn parallelProcess(data: []f64) ![]f64 {
    const allocator = std.heap.page_allocator;
    const result = try allocator.alloc(f64, data.len);
    for (data, result, 0..) |d, *r, i| {
        r.* = d + @as(f64, @floatFromInt(i));
    }
    return result;
}
